fn pick3(p: { ...r }, q: { ...s }, w: { ...t }): { ...r, ...s, ...t }
  where r disjoint s, r disjoint t, s disjoint t = pick3(p, q, w);
fn apply(f: (a, b, c) -> { x: Int, y: Int }, g: (a, b, c) -> Int): Int = 0;
fn noX(p: { ...u }, q: { ...v }, w: { ...o }): Int
  where u lacks { x }, v lacks { x }, o lacks { x } = 0;
fn main(): Int = apply(fn(p: { x: Int }, q: {}, w: { y: Int }) => pick3(p, q, w), noX);
